/* Local JustValidate integration; submission runs only after validation succeeds. */
(()=>{'use strict';const A=Abibi,instances={},phone=v=>/^09\d{9}$/.test(A.digits(v).replace(/[\s-]/g,'')),required=errorMessage=>({rule:'required',errorMessage}),trimmed=(min,max,errorMessage)=>({validator:v=>String(v).trim().length>=min&&String(v).trim().length<=max,errorMessage});
function bind(selector,fields){const form=document.querySelector(selector);if(!form)return;form.noValidate=true;if(!window.JustValidate){form.addEventListener('submit',e=>{e.preventDefault();A.toast('اعتبارسنجی بارگذاری نشد؛ صفحه را دوباره باز کن.')});return}const v=new JustValidate(form,{errorFieldCssClass:'is-invalid',errorLabelCssClass:'validation-message',errorFieldStyle:{},errorLabelStyle:{},focusInvalidField:true,lockForm:true});for(const[field,rules]of Object.entries(fields))v.addField(field,rules);v.onSuccess(()=>form.dispatchEvent(new Event('abibi:valid-submit',{bubbles:true,cancelable:true})));instances[form.id]=v;form.addEventListener('reset',()=>setTimeout(()=>v.refresh(),0));return v}
const phoneRules=[required('شماره موبایل را وارد کن.'),{validator:phone,errorMessage:'شماره موبایل باید ۱۱ رقم باشد و با ۰۹ شروع شود.'}];
const checkout=bind('#checkout-form',{'#customer':[required('نام دریافت‌کننده را بنویس.'),trimmed(3,80,'نام باید بین ۳ تا ۸۰ نویسه باشد.')],'#phone':phoneRules,'#note':[{rule:'maxLength',value:300,errorMessage:'توضیحات حداکثر ۳۰۰ نویسه باشد.'}]});
if(checkout){const f=document.querySelector('#checkout-form');let addressBound=false,scheduleBound=false;function conditional(){const delivery=f.elements.mode.value==='delivery',scheduled=f.elements.timing.value==='scheduled';if(delivery&&!addressBound){checkout.addField('#address',[required('آدرس تحویل را بنویس.'),trimmed(10,400,'آدرس کامل بین ۱۰ تا ۴۰۰ نویسه وارد کن.')]);addressBound=true}else if(!delivery&&addressBound){checkout.removeField('#address');addressBound=false}if(scheduled&&!scheduleBound){checkout.addField('#schedule',[required('تاریخ و ساعت دریافت را انتخاب کن.'),{validator:v=>Number.isFinite(new Date(v).getTime())&&new Date(v)>new Date(),errorMessage:'تاریخ و ساعت باید در آینده باشد.'}]);scheduleBound=true}else if(!scheduled&&scheduleBound){checkout.removeField('#schedule');scheduleBound=false}}conditional();f.addEventListener('change',conditional)}
bind('#login-form',{'#login-phone':phoneRules});bind('#verify-form',{'#demo-code':[required('کد تأیید را وارد کن.'),{validator:v=>A.digits(v).trim()==='1234',errorMessage:'کد نمایشی صحیح ۱۲۳۴ است.'}]});
bind('#profile-form',{'#full-name':[required('نام خودت را بنویس.'),trimmed(3,80,'نام باید بین ۳ تا ۸۰ نویسه باشد.')],'#profile-phone':[{validator:v=>!String(v).trim()||phone(v),errorMessage:'شماره موبایل ۱۱ رقمی با ۰۹ وارد کن.'}],'#email':[{rule:'email',errorMessage:'نشانی ایمیل معتبر وارد کن.'}],'#birthday':[{validator:v=>!v||(Number.isFinite(new Date(v).getTime())&&new Date(v)<=new Date()),errorMessage:'تاریخ تولد معتبر و پیش از امروز وارد کن.'}]});
bind('#address-form',{'#address-title':[required('عنوان آدرس را بنویس.'),trimmed(2,40,'عنوان باید بین ۲ تا ۴۰ نویسه باشد.')],'#address-text':[required('آدرس کامل را بنویس.'),trimmed(10,300,'آدرس کامل بین ۱۰ تا ۳۰۰ نویسه وارد کن.')]});bind('#product-form',{'#food-note':[{rule:'maxLength',value:200,errorMessage:'توضیحات غذا حداکثر ۲۰۰ نویسه باشد.'}]});window.AbibiValidation=instances;
})();
